    function validate(p){if(!p.budget||!p.objectif||!p.distance||!p.terrain||!p.poids||!p.typePied||!p.attaque||!p.pointure||!p.rayon||!p.priorite1||!p.priorite2||!p.priorite3||!p.marque)return"Merci de compléter toutes les informations.";if(new Set([p.priorite1,p.priorite2,p.priorite3]).size<3)return"Les 3 priorités doivent être différentes.";if(p.pointure<35||p.pointure>50||Math.abs(p.pointure*2-Math.round(p.pointure*2))>0.001)return"Entre une pointure comprise entre 35 et 50, par demi-pointure.";return""}
    function personalized(s,p){let n=0,d=0;const ps=[p.priorite1,p.priorite2,p.priorite3];CR.forEach(([c,k])=>{let co=1,idx=ps.indexOf(c);if(idx>=0)co=COEFS[idx];n+=s[k]*co;d+=co});return 10*n/d}
    function budget(s,p){let d=s.prix-p.budget;return d<=0?100:d<=10?90:d<=20?75:d<=30?55:d<=50?30:0}
    function weight(s,p){if(p.poids>s.poidsMax)return 0;if(p.poids>=s.poidsIdealMin&&p.poids<=s.poidsIdealMax)return 100;let d=Math.min(Math.abs(p.poids-s.poidsIdealMin),Math.abs(p.poids-s.poidsIdealMax));return d<=5?90:d<=10?70:d<=15?40:0}
    function tokensDistance(raw){let s=norm(raw),o=[];["< 10 KM","10 - 30 KM","30 - 50 KM","> 50 KM","ULTRA"].forEach(x=>{if(s.includes(norm(x)))o.push(x)});if(/10\s*-\s*50\s*KM/.test(s))o.push("10 - 30 KM","30 - 50 KM");if(/10\s*-\s*(80|100)\s*KM/.test(s))o.push("10 - 30 KM","30 - 50 KM","> 50 KM");if(/30\s*-\s*100\s*KM/.test(s))o.push("30 - 50 KM","> 50 KM","ULTRA");return[...new Set(o)]}
    function distance(s,p){let t=tokensDistance(s.distance);return t.length?Math.max(...t.map(x=>DM[p.distance]?.[x]||0)):0}
    function terrain(s,p){let st=norm(s.terrain),vals=[];["ROULANT","MIXTE","TECHNIQUE","MONTAGNE","TOUTES"].forEach(x=>{if(st.includes(norm(x)))vals.push(TM[p.terrain]?.[x]||0)});if(st.includes("BOUE"))vals.push(TM[p.terrain]?.["TECHNIQUE"]||0);return vals.length?Math.max(...vals):0}
    function foot(s,p){return norm(s.typePied).includes(norm(p.typePied))?100:50}
    function strike(s,p){if(p.attaque==="JE NE SAIS PAS")return 100;let needle=p.attaque==="AVANT-PIED"?"AVANT":(p.attaque==="MÉDIO-PIED"?"MILIEU":p.attaque);return norm(s.attaque).includes(norm(needle))?100:50}
    function brand(s,p){return p.marque==="AUCUNE"?100:(s.marque===p.marque?100:50)}
    function calc(s,p){let sc={personalized:personalized(s,p),objective:OBJ[p.objectif]?.[s.type]||0,budget:budget(s,p),runnerWeight:weight(s,p),distance:distance(s,p),terrain:terrain(s,p),foot:foot(s,p),strike:strike(s,p),brand:brand(s,p)};let final=Object.keys(WEIGHTS).reduce((a,k)=>a+sc[k]*WEIGHTS[k],0);return{...s,sc,final,eligible:p.poids<=s.poidsMax}}
    const pretty=x=>x.replace("STABILITE","STABILITÉ");
    function strengths(s){return CR.map(([l,k])=>[l,s[k]]).sort((a,b)=>b[1]-a[1]).slice(0,3).map(x=>pretty(x[0])).join(" · ")}
    function weak(s){let x=CR.map(([l,k])=>[l,s[k]]).sort((a,b)=>a[1]-b[1])[0];return x[1]<7?pretty(x[0]):""}
    function pv(s,p){let r=CR.find(([l])=>l===p);return r?s[r[1]]:0}
    function why(s,p){let v=[pv(s,p.priorite1),pv(s,p.priorite2),pv(s,p.priorite3)],avg=(v[0]+v[1]+v[2])/3;return`Cette chaussure obtient ${Math.round(s.final)}/100 pour ton profil. ${avg>=8.5?"Elle correspond très bien":"Elle correspond bien"} à tes priorités : ${pretty(p.priorite1).toLowerCase()} ${v[0]}/10, ${pretty(p.priorite2).toLowerCase()} ${v[1]}/10 et ${pretty(p.priorite3).toLowerCase()} ${v[2]}/10.`}
    function budgetLabel(s,p){return s.prix<=p.budget?'<span class="budget-ok">'+mbpIcon("check")+' DANS LE BUDGET</span>':s.prix<=p.budget+20?'<span class="budget-heart">'+mbpIcon("heart")+' COUP DE CŒUR</span>':'<span class="budget-out">'+mbpIcon("alert")+' HORS BUDGET</span>'}

